WITH base AS (SELECT *, UPPER(dept_name) AS dept_name_upper, TRIM(location) AS clean_location FROM departments WHERE dept_name IS NULL) SELECT id, dept_name, location, budget, dept_name_upper, clean_location, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) AS budget_share, LEAD(budget, 2) OVER (ORDER BY budget, id) AS next_budget, SUM(budget) OVER (ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget FROM base;
